import { test, expect } from '@playwright/test';

test.describe('Toast Notifications Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <div id="toast-container" role="region" aria-live="polite" aria-label="Notifications">
        <div id="toast-1" role="alert" aria-live="assertive" class="toast">
          <span class="toast-message">Success: Operation completed</span>
          <button aria-label="Close notification">×</button>
        </div>
      </div>
      <button id="trigger-toast">Show Toast</button>
      <script>
        let toastCount = 1;
        document.getElementById('trigger-toast').addEventListener('click', () => {
          toastCount++;
          const container = document.getElementById('toast-container');
          const toast = document.createElement('div');
          toast.id = 'toast-' + toastCount;
          toast.role = 'alert';
          toast.setAttribute('aria-live', 'assertive');
          toast.className = 'toast';
          toast.innerHTML = '<span class="toast-message">Notification ' + toastCount + '</span><button aria-label="Close notification">×</button>';
          container.appendChild(toast);
          setTimeout(() => {
            toast.remove();
          }, 3000);
        });
      </script>
      <style>
        .toast {
          padding: 12px;
          margin: 8px 0;
          background-color: #4CAF50;
          color: white;
          border-radius: 4px;
          display: flex;
          justify-content: space-between;
          align-items: center;
        }
      </style>
    `);
  });

  test('should have toast container with proper ARIA live region attributes', async ({ page }) => {
    const toastContainer = page.getByRole('region', { name: 'Notifications' });
    await expect(toastContainer).toBeVisible();

    const ariaLive = await toastContainer.getAttribute('aria-live');
    expect(ariaLive).toBe('polite');
  });

  test('should announce toast notifications with assertive aria-live', async ({ page }) => {
    const toast = page.locator('#toast-1');

    const ariaLive = await toast.getAttribute('aria-live');
    expect(ariaLive).toBe('assertive');

    const role = await toast.getAttribute('role');
    expect(role).toBe('alert');
  });

  test('should have accessible close button on toast', async ({ page }) => {
    const closeButton = page.getByRole('button', { name: 'Close notification' }).first();
    await expect(closeButton).toBeVisible();

    const ariaLabel = await closeButton.getAttribute('aria-label');
    expect(ariaLabel).toBe('Close notification');
  });

  test('should dynamically announce new toast notifications', async ({ page }) => {
    const triggerButton = page.getByRole('button', { name: 'Show Toast' });
    await triggerButton.click();

    const newToast = page.locator('#toast-2');
    await expect(newToast).toBeVisible();

    const role = await newToast.getAttribute('role');
    expect(role).toBe('alert');

    const ariaLive = await newToast.getAttribute('aria-live');
    expect(ariaLive).toBe('assertive');
  });

  test('should maintain accessibility attributes when multiple toasts are displayed', async ({ page }) => {
    const triggerButton = page.getByRole('button', { name: 'Show Toast' });

    await triggerButton.click();
    await triggerButton.click();

    const toasts = page.locator('[role="alert"]');
    const count = await toasts.count();
    expect(count).toBeGreaterThanOrEqual(2);

    for (let i = 0; i < count; i++) {
      const toast = toasts.nth(i);
      const role = await toast.getAttribute('role');
      expect(role).toBe('alert');

      const ariaLive = await toast.getAttribute('aria-live');
      expect(ariaLive).toBe('assertive');
    }
  });

  test('should have proper semantic structure for screen reader navigation', async ({ page }) => {
    const toastContainer = page.getByRole('region', { name: 'Notifications' });
    const alerts = toastContainer.locator('[role="alert"]');

    const alertCount = await alerts.count();
    expect(alertCount).toBeGreaterThan(0);

    const firstAlert = alerts.first();
    const message = firstAlert.locator('.toast-message');
    await expect(message).toContainText('Success: Operation completed');
  });
});
